parameters.jsCode:
// Check delivery latency against the stored queue timestamp.
// Alert if delivery took longer than 3 minutes.

const input = $input.first().json;
const messageId = input.messageId;
const deliveredAt = new Date(input.timestamp).getTime();

const tracking = $getWorkflowStaticData('global').emailTracking || {};
const queuedInfo = tracking[messageId];

if (!queuedInfo) {
  return [{ json: { alertNeeded: false, reason: 'No queue record', ...input } }];
}

const latencyMs = deliveredAt - queuedInfo.queuedAt;
const latencySeconds = Math.round(latencyMs / 1000);
const latencyMinutes = (latencyMs / 1000 / 60).toFixed(1);

const THRESHOLD_MS = 3 * 60 * 1000; // 3 minutes
const alertNeeded = latencyMs > THRESHOLD_MS;

// Clean up tracked entry
delete tracking[messageId];
$getWorkflowStaticData('global').emailTracking = tracking;

return [{
  json: {
    alertNeeded,
    latencyMs,
    latencySeconds,
    latencyMinutes,
    recipient: queuedInfo.recipient || input.recipient,
    subject: queuedInfo.subject || input.subject,
    messageId,
    eventType: 'slow_delivery',
    category: alertNeeded ? 'slow' : 'success',
    timestamp: input.timestamp
  }
}];

// Store queued email timestamp for delivery latency tracking.
// When a 'delivered' event arrives later, we compare timestamps.

const input = $input.first().json;
const messageId = input.messageId;
const timestamp = input.timestamp;

if (!messageId || messageId === 'unknown') {
  return [{ json: { stored: false, reason: 'No message ID', ...input } }];
}

let tracking = $getWorkflowStaticData('global').emailTracking || {};

tracking[messageId] = {
  queuedAt: new Date(timestamp).getTime(),
  recipient: input.recipient,
  subject: input.subject
};

// Evict entries older than 24 hours
const cutoff = Date.now() - 24 * 60 * 60 * 1000;
for (const [id, entry] of Object.entries(tracking)) {
  if (entry.queuedAt < cutoff) delete tracking[id];
}

$getWorkflowStaticData('global').emailTracking = tracking;

return [{ json: { stored: true, messageId, ...input } }];

