// Parse Scaleway TEM webhook payload delivered via SNS envelope.
// TEM events arrive wrapped in an SNS message: { Type, Message (JSON string), ... }

const input = $input.first().json;
const body = input.body || input;

// Unwrap SNS envelope if present
let message = body;
if (typeof body.Message === 'string') {
  try {
    message = JSON.parse(body.Message);
  } catch (e) {
    message = body;
  }
}

// Extract event details
const eventType = message.eventType || message.event_type || 'unknown';
const timestamp = message.timestamp || new Date().toISOString();
const messageId = message.mail?.messageId || message.message_id || 'unknown';
const recipient = message.mail?.destination?.[0] || message.recipient || 'unknown';
const subject = message.mail?.commonHeaders?.subject || message.subject || 'N/A';
const source = message.mail?.source || message.sender || 'unknown';

// Categorize event
let category = 'info';
let alertNeeded = false;

switch (eventType) {
  case 'Bounce':
  case 'bounce':
  case 'email_dropped':
  case 'Complaint':
  case 'complaint':
  case 'Reject':
  case 'reject':
    category = 'failure';
    alertNeeded = true;
    break;
  case 'Delivery':
  case 'delivery':
  case 'email_delivered':
    category = 'success';
    break;
  case 'Send':
  case 'send':
  case 'email_queued':
    category = 'queued';
    break;
  case 'DeliveryDelay':
  case 'email_deferred':
    category = 'delayed';
    break;
}

// Extract error details for failures
let errorMessage = '';
if (message.bounce) {
  errorMessage = message.bounce.bouncedRecipients
    ?.map(r => `${r.emailAddress}: ${r.diagnosticCode || r.status}`)
    .join(', ') || 'Bounce detected';
} else if (message.complaint) {
  errorMessage = 'Spam complaint received';
} else if (message.reject) {
  errorMessage = message.reject.reason || 'Rejected';
}

return [{
  json: {
    eventType,
    category,
    alertNeeded,
    messageId,
    recipient,
    subject,
    source,
    timestamp,
    errorMessage,
    rawEvent: message
  }
}];
